import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"官方与社区文档调研","description":"","frontmatter":{},"headers":[],"relativePath":"research/official-docs.md","filePath":"research/official-docs.md","lastUpdated":1791561689000}`),a={name:`research/official-docs.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="官方与社区文档调研" tabindex="-1">官方与社区文档调研 <a class="header-anchor" href="#官方与社区文档调研" aria-label="Permalink to “官方与社区文档调研”">​</a></h1><p>书籍给目录和定义，官方文档给 API 口径，社区站点给分类与别名核对。这三类来源决定了站内正文里的类名、方法名与术语能不能对上现用的工具链。</p><h2 id="官方文档" tabindex="-1">官方文档 <a class="header-anchor" href="#官方文档" aria-label="Permalink to “官方文档”">​</a></h2><h3 id="java-se-java-util-concurrent-s19" tabindex="-1">Java SE：<code>java.util.concurrent</code> [S19] <a class="header-anchor" href="#java-se-java-util-concurrent-s19" aria-label="Permalink to “Java SE：java.util.concurrent [S19]”">​</a></h3><p>并发目录的术语基准。站内引用到的标准库实现：</p><table tabindex="0"><thead><tr><th>站内篇目</th><th>标准库对应</th></tr></thead><tbody><tr><td><a href="/hello-design-patterns/concurrency/semaphore">信号量模式</a></td><td><code>java.util.concurrent.Semaphore</code></td></tr><tr><td><a href="/hello-design-patterns/concurrency/future">Future 模式</a></td><td><code>java.util.concurrent.Future</code>、<code>CompletableFuture</code></td></tr><tr><td><a href="/hello-design-patterns/concurrency/producer-consumer">生产者-消费者模式</a></td><td><code>BlockingQueue</code> 系列</td></tr><tr><td><a href="/hello-design-patterns/concurrency/thread-pool">线程池模式（本次新增）</a></td><td><code>ExecutorService</code>、<code>ThreadPoolExecutor</code></td></tr><tr><td><a href="/hello-design-patterns/concurrency/read-write-lock">读写锁模式（本次新增）</a></td><td><code>ReadWriteLock</code>、<code>ReentrantReadWriteLock</code></td></tr><tr><td><a href="/hello-design-patterns/concurrency/double-checked-locking">双重检查锁定</a></td><td><code>volatile</code> 的 JMM 语义</td></tr></tbody></table><p>口径要留意：<code>Future.get()</code> 是阻塞取值，<code>CompletableFuture</code> 才带组合与回调；<code>Semaphore</code> 的 <code>acquire</code> 可被中断，示例里必须在拿到许可后才 <code>release</code>（站内信号量篇已按此写）。</p><h3 id="c-core-guidelines-s20" tabindex="-1">C++ Core Guidelines [S20] <a class="header-anchor" href="#c-core-guidelines-s20" aria-label="Permalink to “C++ Core Guidelines [S20]”">​</a></h3><p>结构型与并发两处的 C++ 现代写法依据：</p><ul><li>资源用 RAII 表达（资源获取即初始化），<code>shared_ptr</code>/<code>unique_ptr</code> 的所有权规则对应站内<a href="/hello-design-patterns/structural/smart-pointer">智能指针模式</a>；</li><li>回调与可调用对象用 <code>std::function</code> 加 <code>std::visit</code>/lambda 表达，不手写函数指针表，对应<a href="/hello-design-patterns/behavioral/callback">回调模式</a>与<a href="/hello-design-patterns/behavioral/strategy">策略模式</a>；</li><li>接口小而窄、用抽象类表达运行时多态，与<a href="/hello-design-patterns/structural/bridge">桥接模式</a>的抽象与实现分离一致。</li></ul><p>Guidelines 的 R.30/R.31 等条目讲 <code>unique_ptr</code> 与 <code>shared_ptr</code> 的参数传递，站内智能指针篇的示例按&quot;值传递 + 移动&quot;写，与之一致。</p><h3 id="go-官方文档与博客-s21" tabindex="-1">Go 官方文档与博客 [S21] <a class="header-anchor" href="#go-官方文档与博客-s21" aria-label="Permalink to “Go 官方文档与博客 [S21]”">​</a></h3><p>Go 的模式落地方式与 Java、C++ 不同：没有继承，靠接口隐式实现加结构体嵌入。</p><ul><li>策略、模板方法这类&quot;算法可换&quot;的模式在 Go 里用函数类型或小接口表达，对应<a href="/hello-design-patterns/behavioral/strategy">策略模式</a>与<a href="/hello-design-patterns/behavioral/template-method">模板方法模式</a>；</li><li>组合优先于继承在 Go 里是语言默认，对应本次新增的<a href="/hello-design-patterns/evolution/composition-over-inheritance">组合式设计</a>；</li><li>goroutine 加 channel 的流水线写法对应<a href="/hello-design-patterns/concurrency/producer-consumer">生产者-消费者模式</a>，官方博客的 Pipelines and cancellation 一节给出 <code>close</code>、<code>range</code>、<code>select</code> 的正确姿势；</li><li><code>context.Context</code> 承担超时与取消传播，站内 <a href="/hello-design-patterns/structural/remote-proxy">gRPC 远程代理示例</a> 的 Go 代码就带 <code>ctx</code> 参数，这是 Go 侧写超时与取消的默认习惯；责任链一类的中间件同样把 <code>ctx</code> 当第一参数传。</li></ul><h3 id="vue-js-官方文档-s22" tabindex="-1">Vue.js 官方文档 [S22] <a class="header-anchor" href="#vue-js-官方文档-s22" aria-label="Permalink to “Vue.js 官方文档 [S22]”">​</a></h3><p>组合式 API 是&quot;组合式设计&quot;在前端的直接落地：把同一功能的逻辑、状态、生命周期收在一个函数里，而不是按选项分散在 <code>data</code>/<code>methods</code>/<code>computed</code> 里。<a href="/hello-design-patterns/evolution/composition-over-inheritance">组合式设计</a>一节的前端例子按该文档的口径写，包括逻辑复用靠函数返回值组合、不靠 mixin。</p><h3 id="react-官方文档-s23" tabindex="-1">React 官方文档 [S23] <a class="header-anchor" href="#react-官方文档-s23" aria-label="Permalink to “React 官方文档 [S23]”">​</a></h3><p>React 的组件组合路径：自底向上用组件嵌套 + props 组合出 UI，状态不够用时状态提升，重复逻辑用自定义 Hook 收口。与 Vue 组合式 API 同属&quot;组合优于继承&quot;的落地，一起写在<a href="/hello-design-patterns/evolution/composition-over-inheritance">组合式设计</a>里。</p><h3 id="microsoft-learn-net-设计指南-s24" tabindex="-1">Microsoft Learn：.NET 设计指南 [S24] <a class="header-anchor" href="#microsoft-learn-net-设计指南-s24" aria-label="Permalink to “Microsoft Learn：.NET 设计指南 [S24]”">​</a></h3><p>.NET 侧的接口设计、可扩展性与命名约定。站内依赖注入、代理、装饰三篇的 C# 示例遵循它的约定：依赖通过构造函数注入，扩展点用接口而不是虚方法基类。</p><h3 id="spring-官方文档-s27" tabindex="-1">Spring 官方文档 [S27] <a class="header-anchor" href="#spring-官方文档-s27" aria-label="Permalink to “Spring 官方文档 [S27]”">​</a></h3><p>依赖注入的落地事实来源：控制反转是容器负责对象组装，应用代码只声明需要什么。对应<a href="/hello-design-patterns/structural/dependency-injection">依赖注入</a>与<a href="/hello-design-patterns/creational/service-locator">服务定位器</a>的对比一节——两者都把&quot;查找实现&quot;移出业务代码，区别在谁发起装配。</p><h3 id="mdn-web-docs-s28" tabindex="-1">MDN Web Docs [S28] <a class="header-anchor" href="#mdn-web-docs-s28" aria-label="Permalink to “MDN Web Docs [S28]”">​</a></h3><p>前端语言层核对：<code>Proxy</code> 对应<a href="/hello-design-patterns/structural/dynamic-proxy">动态代理</a>与<a href="/hello-design-patterns/structural/protection-proxy">保护代理</a>，迭代器协议对应<a href="/hello-design-patterns/behavioral/iterator">迭代器模式</a>，<code>EventTarget</code> 的 <code>addEventListener</code>/<code>removeEventListener</code> 是观察者模式的语言内置，对应<a href="/hello-design-patterns/behavioral/observer">观察者模式</a>。</p><h2 id="社区站点" tabindex="-1">社区站点 <a class="header-anchor" href="#社区站点" aria-label="Permalink to “社区站点”">​</a></h2><h3 id="refactoring-guru-s16" tabindex="-1">Refactoring.Guru [S16] <a class="header-anchor" href="#refactoring-guru-s16" aria-label="Permalink to “Refactoring.Guru [S16]”">​</a></h3><p>模式条目按语言切示例（Java、C#、Go、TypeScript 等），每个条目给意图、结构、代码与&quot;如何识别要不要用&quot;。站内条目命名与它一致的地方：创建型/结构型/行为型三分法、代理的四个变体（虚拟、保护、远程、动态）、组合与装饰的对比。差异点：它把&quot;空对象&quot;当独立条目，站内没有，记入差异表。</p><h3 id="sourcemaking-s17" tabindex="-1">SourceMaking [S17] <a class="header-anchor" href="#sourcemaking-s17" aria-label="Permalink to “SourceMaking [S17]”">​</a></h3><p>设计模式与反模式条目带 UML 与优缺点段落。站内反模式四篇的结构（形态、成因、代价、怎么走出来）沿用它的段落顺序；术语&quot;意面代码&quot;的中文译法与它对 Spaghetti Code 的处理一致。</p><h3 id="iluwatar-java-design-patterns-s18" tabindex="-1">iluwatar/java-design-patterns [S18] <a class="header-anchor" href="#iluwatar-java-design-patterns-s18" aria-label="Permalink to “iluwatar/java-design-patterns [S18]”">​</a></h3><p>约百个模式条目的 Java 实现仓库，每条含类图与可运行示例。它收录而站内没有的条目，本次按是否在权威书籍目录里出现决定取舍：</p><ul><li>在书里有出处的（空对象、仓储、规格、隔舱、熔断）→ 熔断本次补，其余记入差异表；</li><li>只在社区流传、没有书籍出处的（例如&quot;类别对象&quot;、&quot;环境对象&quot;）→ 不收录。</li></ul><h2 id="交叉核对的结果" tabindex="-1">交叉核对的结果 <a class="header-anchor" href="#交叉核对的结果" aria-label="Permalink to “交叉核对的结果”">​</a></h2><ol><li>站内并发篇的标准库名与 Java SE 文档一致，本次新增的线程池、读写锁两篇直接以 <code>ThreadPoolExecutor</code> 与 <code>ReentrantReadWriteLock</code> 为准。</li><li>站内 C++ 示例的智能指针赋值用 copy-and-swap 写法，与 Guidelines 的资源管理意图一致（本次一并修正了旧版手写自赋值判断的写法）。</li><li>Go 示例不出现&quot;继承&quot;字样，组合写法用嵌入表达。</li><li>前端示例不写 Vue 2 选项式与 React class 组件，统一用组合式 API 与函数组件。</li></ol>`,34)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};